programs.code:
/* Descendant: semua p di dalam .container */
.container p {
    color: blue;
}

/* Child: p yang merupakan anak langsung .container */
.container > p {
    font-size: 18px;
}

/* Adjacent sibling: p yang langsung setelah section */
section + p {
    color: red;
}

/* General sibling: semua p setelah section */
section ~ p {
    font-weight: bold;
}

